input.query:
SELECT count(DISTINCT im."ENSG ID"), count(DISTINCT ms."ENSG ID"), count(DISTINCT CASE WHEN im."ENSG ID" IS NOT NULL AND ms."ENSG ID" IS NOT NULL THEN COALESCE(im."ENSG ID", ms."ENSG ID") END)
FROM blood_immunoassay_concentration im
FULL OUTER JOIN blood_ms_concentration ms ON im."ENSG ID" = ms."ENSG ID";
